effect.shader:
float hashV(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float noiseV(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
f = f*f*(3.0-2.0*f);
return mix(
mix(hashV(i),           hashV(i+vec2(1,0)), f.x),
mix(hashV(i+vec2(0,1)), hashV(i+vec2(1,1)), f.x),
f.y
);
}
vec3 rainbow(float t) {
t = fract(t);
float r = abs(t * 6.0 - 3.0) - 1.0;
float g = 2.0 - abs(t * 6.0 - 2.0);
float b = 2.0 - abs(t * 6.0 - 4.0);
return clamp(vec3(r, g, b), 0.0, 1.0);
}
vec2 getWaveDisplace(vec2 dotIdx, float t) {
float pr   = float(preset);
float freq = frequency * 0.0001;
float ph   = phase * 3.14159 / 180.0;
float spd  = t * animSpeed;
float col  = dotIdx.x;
float row  = dotIdx.y;
float ori  = float(orientation);
vec2  disp = vec2(0.0);
float axis = (ori < 0.5) ? col : row;
if (pr < 0.5) {
float w = sin(axis * freq * 50.0 + spd + ph) * distortion;
disp = (ori < 0.5) ? vec2(0.0, w) : vec2(w, 0.0);
} else if (pr < 1.5) {
float w = sign(sin(axis * freq * 50.0 + spd + ph)) * distortion * 0.5;
disp = (ori < 0.5) ? vec2(0.0, w) : vec2(w, 0.0);
} else if (pr < 2.5) {
float wx = sin(col * freq * 80.0 + spd + ph)        * distortion * 0.5
+ sin(col * freq * 130.0 + spd * 1.3)      * distortion * 0.3
+ noiseV(vec2(col*freq*10.0, spd*0.3))     * distortion * 0.2;
float wy = sin(row * freq * 70.0 + spd * 0.8 + ph)  * distortion * 0.4
+ sin(row * freq * 110.0 + spd * 1.1)      * distortion * 0.3;
disp = vec2(wx, wy);
} else if (pr < 3.5) {
vec2 center = vec2(acPreviewSize.x / pitch, acPreviewSize.y / pitch) * 0.5;
float dist  = length(dotIdx - center);
float w     = sin(dist * freq * 100.0 - spd + ph) * distortion;
vec2 dir    = normalize(dotIdx - center + vec2(0.001));
disp = dir * w;
} else if (pr < 4.5) {
disp = vec2(0.0);
} else if (pr < 5.5) {
float gc  = floor(col / max(density, 1.0));
float gt  = floor(spd * 3.0);
float rnd = (hashV(vec2(gc + gt, row)) * 2.0 - 1.0);
float fired = step(0.6, hashV(vec2(gc, gt + 1.0)));
disp = vec2(rnd * distortion * 2.0 * fired, 0.0);
} else if (pr < 6.5) {
float w = (fract(axis * freq * 30.0 + spd) * 2.0 - 1.0) * distortion;
disp = (ori < 0.5) ? vec2(0.0, w) : vec2(w, 0.0);
} else if (pr < 7.5) {
float wx = sin(col * freq * 40.0 + spd)             * distortion * 0.4
+ sin(row * freq * 30.0 + spd * 0.7 + ph)  * distortion * 0.3;
float wy = sin(row * freq * 40.0 + spd * 0.8)       * distortion * 0.4
+ sin(col * freq * 25.0 + spd * 1.1 + ph)  * distortion * 0.3;
disp = vec2(wx, wy);
} else {
float pt  = floor(spd * 2.0);
float rdx = (hashV(vec2(col + pt, row + 0.1)) * 2.0 - 1.0);
float rdy = (hashV(vec2(col + 0.2, row + pt)) * 2.0 - 1.0);
float burst = step(0.5, hashV(vec2(col * 0.1, row * 0.1 + pt)));
disp = vec2(rdx, rdy) * distortion * burst;
}
for (int g = 1; g < 10; g++) {
if (float(g) >= generators) break;
float gf = float(g);
float gOff = gf * 0.618;
disp += disp * sin(gOff * 3.14159 + animSpeed * acTime) * 0.2 / gf;
}
return disp;
}
void main() {
vec2 uv  = acScreenNorm;
float t  = acTime;
vec4 src = texture2DCv(inputImg.texture, clamp(uv, 0.0, 1.0));
float cellSize = pitch;
vec2 pixelPos  = uv * acPreviewSize;
vec2 dotIdx  = floor(pixelPos / cellSize);
vec2 cellUV  = fract(pixelPos / cellSize);
vec2 waveDisp   = getWaveDisplace(dotIdx, t);
waveDisp += vec2(xShift, yShift) * 0.01;
waveDisp *= compress;
vec2 dotCenter  = (dotIdx + 0.5 + waveDisp) * cellSize / acPreviewSize;
dotCenter       = clamp(dotCenter, 0.0, 1.0);
vec3 srcCol  = texture2DCv(inputImg.texture, dotCenter).rgb;
float luma   = dot(srcCol, vec3(0.299, 0.587, 0.114));
float lumaAdj = (luma - cutoff) / max(range, 0.001);
lumaAdj = clamp(lumaAdj, 0.0, 1.0);
lumaAdj = smoothstep(fade * 0.3, fade * 0.3 + 0.2, lumaAdj);
lumaAdj = pow(lumaAdj, 1.0 + decay * 0.3);
float baseRad  = thickness / cellSize * 0.45;
baseRad        = clamp(baseRad, 0.01, 0.48);
float dotRadius = baseRad * lumaAdj;
dotRadius       = clamp(dotRadius, 0.0, 0.48);
vec2 fromCenter = cellUV - 0.5;
float dist      = length(fromCenter);
float dotMask = 1.0 - smoothstep(dotRadius * 0.7, dotRadius, dist);
float cm = float(colorMode);
vec3 dotColor;
if (cm < 0.5) {
dotColor = srcCol;
} else if (cm < 1.5) {
dotColor = vec3(colorR, colorG, colorB);
} else {
float rainbowT = (dotIdx.x + dotIdx.y * 0.3) / (acPreviewSize.x / cellSize);
dotColor = rainbow(rainbowT + t * animSpeed * 0.1);
}
float glowRadius = dotRadius + (glow / cellSize) * 0.3;
glowRadius       = clamp(glowRadius, dotRadius, 0.8);
float glowFalloff = 1.0 - smoothstep(dotRadius, glowRadius, dist);
glowFalloff = glowFalloff * glowFalloff;
vec3 result = vec3(0.0);
result += dotColor * glowFalloff * lumaAdj * glow * 0.15;
result += dotColor * dotMask * lumaAdj;
result = clamp(result, 0.0, 1.0);
gl_FragColor = vec4(mix(src.rgb, result, blend), src.a);
}
